def REToFSA(re) -> FiniteStateAutomaton:
  global QC
  if re == '':
    q = QC
    QC += 1
    return FiniteStateAutomaton(set(), {q}, set(), q, {q})
  elif type(re) == str:
    q = QC
    QC += 1
    r = QC
    QC += 1
    return FiniteStateAutomaton({re}, {q, r}, {(q, re, r)}, q, {r})
  elif type(re) == Choice:
    A1, A2 = REToFSA(re.e1), REToFSA(re.e2)
    R2 = {
      (A1.q0 if q == A2.q0 else q, a, r) for (q, a, r) in A2.R
    }  # A2.q0 renamed to A1.q0 in A2.R
    F2 = {
      A1.q0 if q == A2.q0 else q for q in A2.F
    }  # A2.q0 renamed to A1.q0 in A2.F
    return FiniteStateAutomaton(
      A1.T | A2.T, A1.Q | A2.Q, A1.R | R2, A1.q0, A1.F | F2
    )
  elif type(re) == Conc:
    A1, A2 = REToFSA(re.e1), REToFSA(re.e2)
    R = (
      A1.R
      | {(f, a, r) for (q, a, r) in A2.R if q == A2.q0 for f in A1.F}
      | {(q, a, r) for (q, a, r) in A2.R if q != A2.q0}
    )
    F = (A2.F - {A2.q0}) | (A1.F if A2.q0 in A2.F else set())
    return FiniteStateAutomaton(A1.T | A2.T, A1.Q | A2.Q, R, A1.q0, F)
  elif type(re) == Star:
    A = REToFSA(re.e)
    R = A.R | {(f, a, r) for (q, a, r) in A.R if q == A.q0 for f in A.F}
    return FiniteStateAutomaton(A.T, A.Q, R, A.q0, {A.q0} | A.F)
  else:
    raise Exception('not a regular expression')


def convertRegExToFSA(re) -> FiniteStateAutomaton:
  global QC
  QC = 0
  return REToFSA(re)
