def deterministicFSA(
  fsa: FiniteStateAutomaton, trace=False
) -> FiniteStateAutomaton:
  qʹ0 = set({fsa.q0})
  Qʹ, Rʹ, visited = {qʹ0}, set(), set()
  if trace:
    print(Qʹ, Rʹ, visited)
  while visited != Qʹ:
    qʹ = (Qʹ - visited).pop()
    visited |= {qʹ}
    for t in fsa.T:
      rʹ = {r for (q, u, r) in fsa.R if u == t and q in qʹ}
      if rʹ != set():
        Qʹ |= {set(rʹ)}
        Rʹ |= {(qʹ, t, set(rʹ))}
    if trace:
      print(Qʹ, Rʹ, visited)
  Fʹ = {qʹ for qʹ in Qʹ for f in fsa.F if f in qʹ}
  return FiniteStateAutomaton(fsa.T, Qʹ, Rʹ, qʹ0, Fʹ)


def accepts(fsa: FiniteStateAutomaton, τ: str) -> bool:
  δ = {(q, a): r for (q, a, r) in fsa.R}
  q = fsa.q0
  for t in τ:
    if (q, t) in δ:
      q = δ[q, t]
    else:
      return False
  return q in fsa.F
